import contextlib
import importlib
import io

stdout = io.StringIO()
stderr = io.StringIO()
with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
    roman = importlib.import_module("roman")
assert stdout.getvalue() == ""
assert stderr.getvalue() == ""
assert [name for name in vars(roman) if not name.startswith("_")] == ["to_roman"]

expected = {
    1: "I", 3: "III", 4: "IV", 9: "IX", 14: "XIV", 40: "XL",
    90: "XC", 400: "CD", 1994: "MCMXCIV", 2026: "MMXXVI",
    3999: "MMMCMXCIX",
}
for value, numeral in expected.items():
    assert roman.to_roman(value) == numeral

values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
def decode(text):
    total = 0
    for index, symbol in enumerate(text):
        value = values[symbol]
        total += -value if index + 1 < len(text) and value < values[text[index + 1]] else value
    return total
for value in range(1, 4000):
    numeral = roman.to_roman(value)
    assert numeral.isupper() and decode(numeral) == value

for value in (0, -1, 4000):
    try:
        roman.to_roman(value)
    except ValueError:
        pass
    else:
        raise AssertionError(f"Expected ValueError for {value!r}")
for value in ("5", 5.0, True):
    try:
        roman.to_roman(value)
    except TypeError:
        pass
    else:
        raise AssertionError(f"Expected TypeError for {value!r}")
print("acceptance checks passed")
